once completed — shared by the\n40\t *  writer (markCompleted) and any reader (history view) so the path is\n41\t *  defined exactly once. */\n42\texport function promptSessionArchivePath(cwd: string, promptSessionId: string): string {\n43\t  return `${cwd.replace(/\\/+$/, '')}/session-manager-operations/prompt-sessions/${promptSessionId}.json`\n44\t}\n45\t\n46\t/** Where a cwd's *active* (not-yet-completed) PromptSessions + their event\n47\t *  chains are persisted — a single per-cwd index, written on every create/\n48\t *  append so a reload never loses in-progress work (unlike the archive,\n49\t *  which is written once at completion). Sibling of promptSessionArchivePath\n50\t *  under the same prompt-sessions/ root, so both live in one place to grep. */\n51\texport function promptSessionActiveIndexPath(cwd: string): string {\n52\t  return `${cwd.replace(/\\/+$/, '')}/session-manager-operations/prompt-sessions/active-index.json`\n53\t}\n54\t\n55\tinterface PromptSessionActiveIndex {\n56\t  sessions: Record<string, PromptSession>\n57\t  events: Record<string, PromptSessionEvent[]>\n58\t}\n59\t\n60\t/**\n61\t * One step in a PromptSession's Prompt → PRD → Response → ... → Closed\n62\t * chain. `causedByEventId` strongly links each event to the exact prior\n63\t * event it followed from, so the full history can be reconstructed and\n64\t * audited later — referential integrity is an explicit requirement, not a\n65\t * nice-to-have.\n66\t */\n67\texport interface PromptSessionEvent {\n68\t  id: string\n69\t  promptSessionId: string\n70\t  kind: 'prompt' | 'prd_created' | 'response' | 'closed'\n71\t  /** FK to the exact prior event this one followed from — must be the\n72\t   *  session's current tail event (chain, not a tree). Null only for the\n73\t   *  first 'prompt' event in a session. */\n74\t  causedByEventId: string | null\n75\t  at: string\n76\t  /** Required for kind: 'prd_created' — the PRD's actual filename/slug. */\n77\t  prdSlug?: string\n78\t  /** Free-