indow.api-unavailable semantics. */\n111\t  hydrateArchived: (cwd: string) => Promise<void>\n112\t}\n113\t\n114\tlet seq = 0\n115\tfunction mintId(prefix: string): string {\n116\t  seq += 1\n117\t  return `${prefix}-${Date.now().toString(36)}-${seq}`\n118\t}\n119\t\n120\t// Two independent fire-and-forget writes to the SAME path (e.g.\n121\t// resumeArchived's createPromptSession call immediately followed by its own\n122\t// persistActiveIndex call) are each an unawaited tmp+rename IPC round-trip —\n123\t// without serialization, whichever rename lands on disk *last* wins, not\n124\t// whichever was *issued* last, which could silently drop the later write's\n125\t// data. Chaining every write for a given path behind the previous one's\n126\t// settlement (success or failure) preserves issue order without the callers\n127\t// (synchronous store actions) needing to await anything.\n128\tconst pendingWritesByPath = new Map<string, Promise<void>>()\n129\t\n130\t/** Fire-and-forget persist of a cwd's active-session slice — called after\n131\t *  every mutation so a reload never loses in-progress work. Best-effort: a\n132\t *  write failure is logged, never thrown into the caller (createPromptSession\n133\t *  and appendPromptSessionEvent are synchronous APIs their callers don't\n134\t *  await). No-ops outside a renderer (tests that never stub window.api). */\n135\tfunction persistActiveIndex(cwd: string, sessions: Record<string, PromptSession>, events: Record<string, PromptSessionEvent[]>): void {\n136\t  if (typeof window === 'undefined' || !window.api?.config?.writeJson) return\n137\t  const index: PromptSessionActiveIndex = {\n138\t    sessions: Object.fromEntries(\n139\t      Object.entries(sessions).filter(([, s]) => s.cwd === cwd && s.status === 'active'),\n140\t    ),\n141\t    events: {},\n142\t  }\n143\t  for (const id of Object.keys(index.sessions)) {\n144\t    index.events[id] = events[id] ?? []\n145\t  }\n146\t  const path = promptSessionActiveIndexPath(cwd)\n147\t  const prior = pendingWritesByPath.get(path) ?? Promise.resolve()\n148\t  const next = prior.then(() => window.api!.config.writeJson(path, index)).then(\n149\t    () => undefined,\n150\t    (err: unknown) => {\n151\t      const msg = err instanceof Error ? err.message : String(err)\n152\t      window.api?.logs?.write('promptSessions', 'warn', `persistActiveIndex failed for ${cwd}: ${msg}`)\n153\t    },\n154\t  )\n155\t  pendingWritesByPath.set(path, next)\n156\t}\n157\t\n158\texport const usePromptSessions = create<PromptSessionsState>((set, get) => ({\n159\t  sessions: {},\n160\t  events: {},\n161\t  createPromptSession: (cwd, goalText, tag) => {\n162\t    const now = new Date().toISOString()\n163\t    const session: PromptSession = {\n164\t      id: mintId('psess'),\n165\t      cwd,\n166\t      goalText,\n167\t      claudeSessionId: crypto.randomUUID(),\n168\t      status: 'active',\n169\t      createdAt: now,\n170\t      completedAt: null,\n171\t      ...(tag ? { tag } : {}),\n172\t    }\n173\t    const firstEvent: PromptSessionEvent = {\n174\t      id: mintId('pevt'),\n175\t      promptSessionId: session.id,\n176\t      kind: 'prompt',\n177\t      causedByEventId: null,\n178\t      at: now,\n179\t      text: goalText,\n180\t    }\n181\t    const sessions = { ...get().sessions, [session.id]: session }\n182\t    const events = { ...get().events, [session.id]: [firstEvent] }\n183\t    set({ sessions, events })\n184\t    persistActiveIndex(cwd, sessions, events)\n185\t    return session\n186\t  },\n187\t  appendPromptSessionEvent: (promptSessionId, event) => {\n188\t    if (!get().sessions[promptSessionId]) {\n189\t      throw new Error(`appendPromptSessionEvent: no PromptSession with id \"${promptSessionId}\"`)\n190\t    }\n191\t    const existing = get().events[promptSessionId] ?? []\n192\t    const tail = existing[existing.length - 1] ?? null\n193\t    if (event.causedByEventId !== null) {\n194\t      // A chain, not a tree: the referenced event must be the session's\n195\t      // current tail — the exact prior event, not merely some earlier one.\n196\t      if (!tail || event.causedByEventId !== tail.id) {\n197\t        throw new Error(\n198\t          `appendPromptSessionEvent: causedByEventId \"${event.causedByEventId}\" does not reference the current tail event of promptSession \"${promptSessionId}\"`,\n199\t        )\n200\t      }\n201\t    } else if (existing.length > 0) {\n202\t      throw new Error(\n203\t        `appendPromptSessionEvent: causedByEventId may only be null for a session's first event (promptSession \"${promptSessionId}\" already has ${existing.length})`,\n204\t      )\n205\t    }\n206\t    if (event.kind === 'prd_created' && !event.prdSlug) {\n207\t      throw new Error(\"appendPromptSessionEvent: kind 'prd_created' requires prdSlug\")\n208\t    }\n209\t    const fullEvent: PromptSessionEvent = {\n210\t      ...event,\n211\t      id: mintId('pevt'),\n212\t      promptSessionId,\n213\t      at: new Date().toISOString(),\n214\t    }\n215\t    const events = { ...get().events, [promptSessionId]: [...existing, fullEvent] }\n216\t    set({ events })\n217\t    const session = get().sessions[promptSessionId]\n218\t    persistActiveIndex(session.cwd, get().sessions, events)\n219\t    return fullEvent\n220\t  },\n221\t  markCompleted: async (promptSessionId) => {\n222\t    const session = get().sessions[promptSessionId]\n223\t    if (!session) {\n224\t      throw new Error(`markCompleted: no PromptSession with id \"${promptSessionId}\"`)\n225\t    }\n226\t    if (session.status === 'completed') return\n227\t\n228\t    // Real kill path: a PromptSession's live process is a chatRunner child\n229\t    // process keyed by promptSessionId (chat.ts's chatKey), not a pty.cjs\n230\t    // tab — claudeSessionId was never registered with PtyManager. Cancel it\n231\t    // for real, and also hit pty:kill on claudeSessionId as the AC's named\n232\t    // reuse path (a harmless no-op today, cheap insurance if tha