{"parentUuid":"e7f3d298-53d7-4f16-a93b-d3e3adc8dd99","isSidechain":false,"promptId":"6800d135-96ed-40a5-8847-ead32c31e93b","type":"user","message":{"role":"user","content":[{"tool_use_id":"toolu_01FgnWLeLdz47gYFye71AALg","type":"tool_result","content":"1\timport { useEffect, useRef, useState } from 'react'\n2\timport { useChat } from '../../state/chat'\n3\timport { usePromptSessions, type PromptSession, type PromptSessionEvent } from '../../state/promptSessions'\n4\timport { useScheduleState } from '../../state/scheduleState'\n5\timport { useEpicTerminal, type EpicTerminalMode } from '../../state/epicTerminal'\n6\timport { EpicTerminalPane } from './EpicTerminalPane'\n7\timport { epicDisplayStatus, epicPrds, epicStats, type EpicSnapshots, type EpicPrd } from '../../lib/epicDerive'\n8\timport { EpicStatusChip, EpicKindTag } from './epic-primitives'\n9\timport { ProjectTag, PrdStatusPill, SchBadge, verdictLabel, type PrdDisplayStatus } from '../tabs/scheduler/sched-primitives'\n10\timport { Turn } from '../ChatTranscriptTurn'\n11\timport { openPrdSlug } from '../../lib/epicNav'\n12\timport { ViewTabs } from '../ui/ViewTabs'\n13\timport { AlmanacIcon } from '../layout/AlmanacIcon'\n14\timport { RunLogViewer } from '../tabs/plans/RunLogViewer'\n15\timport { formatAgo, formatDuration, formatTimingLabel } from '../../lib/formatTime'\n16\timport { toast } from '../../state/toast'\n17\timport { useScheduledPrds } from '../../lib/useScheduledPrds'\n18\timport { useBranch } from '../../lib/useBranch'\n19\timport type { ScheduleJob } from '../../../preload/api'\n20\t\n21\t/**\n22\t * Right pane of the redesigned Epics workspace — header (status/kind/project\n23\t * tags, title, goal, actions) + meta row + Discussion/PRDs/Runs view tabs.\n24\t * Built from session-manager-operations/design-mocks/epics/DESIGN_SPEC.md\n25\t * (\"Right pane\") + epics-mock.jsx's EpicDetail/Turn/ToolStrip, translated\n26\t * from inline styles to Tailwind Almanac tokens.\n27\t *\n28\t * Supersedes PromptSessionConversation.tsx as the Epic conversation surface\n29\t * (that file is retired by PRD 829, not here — keep it compiling until then).\n30\t * The Discussion timeline reuses PromptSessionConversation's own merge logic\n31\t * (chat turns + prd_created/closed events, sorted by time) and the shared\n32\t * Turn renderer from ChatTranscriptTurn.tsx, extended behind two new props\n33\t * (toolStripVariant, needsDecisionStyle) rather than forked.\n34\t *\n35\t * PRDs/Runs tab real content is PRD 828's sibling — this file renders\n36\t * placeholder empty states for both. The composer (827-epic-composer) and\n37\t * New Epic card (827-new-epic-card) are separate wave siblings; this file\n38\t * never renders a composer.\n39\t */\n40\t\n41\tconst EMPTY_EVENTS: PromptSessionEvent[] = []\n42\tconst EMPTY_JOBS: ScheduleJob[] = []\n43\t\n44\ttype ViewKey = 'discussion' | 'prds' | 'runs'\n45\t\n46\tfunction MetaItem({ label, value }: { label: string; value: string }) {\n47\t  return (\n48\t    <span className=\"inline-flex items-baseline gap-1.5 text-xs\" data-testid=\"epic-meta-item\">\n49\t      <span className=\"text-fg-faint\">{label}</span>\n50\t      <span className=\"font-mono font-semibold text-fg-dim\">{value}</span>\n51\t    </span>\n52\t  )\n53\t}\n54\t\n55\tfunction EmptyPlaceholder({ text }: { text: string }) {\n56\t  return (\n57\t    <div className=\"rounded-xl border border-dashed border-rule px-6 py-8 text-center text-sm leading-relaxed text-fg-faint\">\n58\t      {text}\n59\t    </div>\n60\t  )\n61\t}\n62\t\n63\t// Relative ages per the mock's EMeta (\"opened 2 days ago · last activity\n64\t// 26m ago\") — absolute timestamps read as a log, not an almanac.\n65\tfunction formatWhen(value: string | number): string {\n66\t  const d = new Date(value)\n67\t  return Number.isNaN(d.getTime()) ? '—' : formatAgo(d.getTime(), Date.now())\n68\t}\n69\t\n70\t/** A PRD file with no matching queue.json job row reads 'draft'\n71\t *  (epicPrds.status carries the raw ScheduleJobStatus otherwise) — map the\n72\t *  one status word STATUS_TONE doesn't key on ('pending') to its Almanac\n73\t *  display name ('queued') rather than forking a second tone table. */\n74\tfunction prdPillStatus(status: EpicPrd['status']): PrdDisplayStatus {\n75\t  return status === 'pending' ? 'queued' : (status as PrdDisplayStatus)\n76\t}\n77\t\n78\t/** Lazy, cached PRD line count — no field for this on EpicPrd/PrdListItem,\n79\t *  so this reads the file body via schedule.readPrd on first render of each\n80\t *  slug and remembers the result module-wide (cards remount often as the\n81\t *  Epic list re-groups/re-sorts). Absent in test mocks that don't stub\n82\t *  readPrd — guarded, so those cards just render without a line count. */\n83\tconst prdLineCountCache = new Map<string, number | null>()\n84\t\n85\tfunction usePrdLineCount(slug: string): number | null {\n86\t  const [count, setCount] = useState<number | null>(() => prdLineCountCache.get(slug) ?? null)\n87\t\n88\t  useEffect(() => {\n89\t    const cached = prdLineCountCache.get(slug)\n90\t    if (cached !== undefined) {\n91\t      setCount(cached)\n92\t      return\n93\t    }\n94\t    if (typeof window.api?.schedule?.readPrd !== 'function') return\n95\t    let cancelled = false\n96\t    window.api.schedule\n97\t      .readPrd(slug)\n98\t      .then((res) => {\n99\t        const lines = res.ok && res.text ? res.text.split('\\n').length : null\n100\t        prdLineCountCache.set(slug, lines)\n101\t        if (!cancelled) setCount(lines)\n102\t      })\n103\t      .catch(() => {\n104\t        prdLineCountCache.set(slug, null)\n105\t        if (!cancelled) setCount(null)\n106\t      })\n107\t    return () => {\n108\t      cancelled = true\n109\t    }\n110\t  }, [slug])\n111\t\n112\t  return count\n113\t}\n114\t\n115\tfunction PrdCard({ prd }: { prd: EpicPrd }) {\n116\t  const lineCount = usePrdLineCount(prd.slug)\n117\t  return (\n118\t    <div\n119\t      className=\"grid grid-cols-[18px_minmax(0,1fr)_auto] items-start gap-3 rounded-xl border border-line bg-bg-hi p-3.5\"\n120\t      data-testid=\"epic-prd-card\"\n121\t    >\n122\t      <span className=\"mt-0.5 text-accent\" aria-hidden=\"true\">\n123\t        <AlmanacIcon name=\"file\" size={16} />\n124\t      </span>\n125\t      <span className=\"min-w-0\">\n126\t        <span className=\"flex flex-wrap items-center gap-2\">\n127\t          <span className=\"font-mono text-[12.5px] font-semibold text-fg\">{prd.slug}</span>\n128\t          <PrdStatusPill status={prdPillStatus(prd.status)} />\n129\t          {lineCount !== null && (\n130\t            <span className=\"font-mono text-[11px] text-fg-faint\" data-testid=\"epic-prd-line-count\">\n131\t              {lineCount} lines\n132\t            </span>\n133\t          )}\n134\t        </span>\n135\t        {prd.title && <span className=\"mt-1 block text-[12.5px] leading-relaxed text-fg-faint\">{prd.title}</span>}\n136\t      </span>\n137\t      <button\n138\t        type=\"button\"\n139\t        onClick={() => openPrdSlug(prd.slug)}\n140\t        title={`Open PRD \"${prd.slug}\" in Scheduler`}\n141\t        data-testid=\"epic-prd-open\"\n142\t        className=\"inline-flex items-center text-fg-faint hover:text-fg-dim\"\n143\t      >\n144\t        <AlmanacIcon name=\"arrowright\" size={15} />\n145\t      </button>\n146\t    </div>\n147\t  )\n148\t}\n149\t\n150\tfunction RunCard({ job }: { job: ScheduleJob }) {\n151\t  const [showLog, setShowLog] = useState(false)\n152\t  const startedMs = job.startedAt ? Date.parse(job.startedAt) : null\n153\t  const finishedMs = job.finishedAt ? Date.parse(job.finishedAt) : null\n154\t  const runtime =\n155\t    startedMs !== null && finishedMs !== null\n156\t      ? formatTimingLabel(finishedMs - startedMs)\n157\t      : startedMs !== null && job.status === 'running'\n158\t        ? formatDuration(Date.now() - startedMs)\n159\t        : null\n160\t\n161\t  return (\n162\t    <div className=\"grid gap-2 rounded-xl border border-line bg-bg-hi p-3.5\" data-testid=\"epic-run-card\">\n163\t      <div className=\"flex flex-wrap items-center gap-2.5\">\n164\t        <span className=\"font-mono text-[12.5px] font-semibold text-fg\">{job.slug}</span>\n165\t        <SchBadge status={job.status} />\n166\t        {runtime && <span className=\"font-mono text-[11px] text-fg-faint\">{runtime}</span>}\n167\t        {job.exitCode !== null && <span className=\"font-mono text-[11px] text-fg-faint\">exit {job.exitCode}</span>}\n168\t        {job.verifierVerdict && (\n169\t          <span className=\"font-mono text-[11px] text-fg-faint\">{verdictLabel(job.verifierVerdict)}</span>\n170\t        )}\n171\t        {job.runId && (\n172\t          <button\n173\t            type=\"button\"\n174\t            onClick={() => setShowLog(true)}\n175\t            data-testid=\"epic-run-view-log\"\n176\t            className=\"ml-auto text-[11.5px] font-semibold text-fg-dim hover:text-fg\"\n177\t          >\n178\t            View log →\n179\t          </button>\n180\t        )}\n181\t      </div>\n182\t      <div className=\"flex flex-wrap gap-3 font-mono text-[11px] text-fg-faint\">\n183\t        <span>started {startedMs !== null ? formatAgo(startedMs, Date.now()) : '—'}</span>\n184\t        <span>finished {finishedMs !== null ? formatAgo(finishedMs, Date.now()) : '—'}</span>\n185\t      </div>\n186\t      {showLog && job.runId && (\n187\t        <RunLogViewer runId={job.runId} slug={job.slug} title={job.title || job.slug} onClose={() => setShowLog(false)} />\n188\t      )}\n189\t    </div>\n190\t  )\n191\t}\n192\t\n193\t/** NewEpicCard.tsx writes goalText as `${title}\\n\\n${goal}` (no separate\n194\t *  title field on PromptSession) — split back apart for the header's h1 +\n195\t *  goal paragraph. Older/Epics with no blank-line separator render the\n196\t *  whole text as the title with no goal paragraph. */\n197\tfunction splitTitleAndGoal(goalText: string): { title: string; goal: string } {\n198\t  const idx = goalText.indexOf('\\n\\n')\n199\t  if (idx === -1) return { title: goalText, goal: '' }\n200\t  return { title: goalText.slice(0, idx), goal: goalText.slice(idx + 2) }\n201\t}\n202\t\n203\t/** Latest activity timestamp across the Epic's audit events + chat turns,\n204\t *  falling back to the Epic's own createdAt when neither has fired yet. */\n205\tfunction lastActivityAt(session: PromptSession, events: PromptSessionEvent[], turns: { at: number }[]): number {\n206\t  const times = [\n207\t    ...events.map((e) => Date.parse(e.at)),\n208\t    ...turns.map((t) => t.at),\n209\t  ].filter((n) => !Number.isNaN(n))\n210\t  if (!times.length) return Date.parse(session.createdAt)\n211\t  return Math.max(...times)\n212\t}\n213\t\n214\tinterface Props {\n215\t  promptSession: PromptSession\n216\t}\n217\t\n218\texport function EpicDetail({ promptSession }: Props) {\n219\t  const epicId = promptSession.id\n220\t  const { cwd, claudeSessionId: sessionId } = promptSession\n221\t  const isCompleted = promptSession.status === 'completed'\n222\t\n223\t  const chat = useChat((s) => s.chats[epicId])\n224\t  const hydrate = useChat((s) => s.hydrate)\n225\t  const sessions = usePromptSessions((s) => s.sessions)\n226\t  const sessionEvents = usePromptSessions((s) => s.events[epicId]) ?? EMPTY_EVENTS\n227\t  const markCompleted = usePromptSessions((s) => s.markCompleted)\n228\t  const resumeArchived = usePromptSessions((s) => s.resumeArchived)\n229\t  const appendPromptSessionEvent = usePromptSessions((s) => s.appendPromptSessionEvent)\n230\t  const scheduleJobs = useScheduleState((s) => s.snapshot?.jobs) ?? EMPTY_JOBS\n231\t\n232\t  const mode = useEpicTerminal((s) => s.modes[epicId] ?? 'chat')\n233\t  const setMode = useEpicTerminal((s) => s.setMode)\n234\t\n235\t  const [view, setView] = useState<ViewKey>('discussion')\n236\t  const prds = useScheduledPrds()\n237\t  const [markingCompleted, setMarkingCompleted] = useState(false)\n238\t  const scrollRef = useRef<HTMLDivElement | null>(null)\n239\t\n240\t  useEffect(() => {\n241\t    void hydrate({ tabId: epicId, cwd, sessionId })\n242\t    // eslint-disable-next-line react-hooks/exhaustive-deps\n243\t  }, [epicId])\n244\t\n245\t  // Tab state resets to Discussion on every Epic change.\n246\t  useEffect(() => {\n247\t    setView('discussion')\n248\t  }, [epicId])\n249\t\n250\t  const turns = chat?.turns ?? []\n251\t  const running = chat?.running ?? false\n252\t\n253\t  // Merged timeline: chat turns + this Epic's own 'prd_created'/'closed'/\n254\t  // 'response' (Terminal-stint marker, PRD 831) audit events, ordered by\n255\t  // time — mirrors PromptSessionConversation.tsx's timeline construction.\n256\t  const timeline = [\n257\t    ...turns.map((t) => ({ kind: 'turn' as const, at: t.at, turn: t })),\n258\t    ...sessionEvents\n259\t      .filter((e): e is PromptSessionEvent & { kind: 'prd_created' | 'closed' | 'response' } =>\n260\t        e.kind === 'prd_created' || e.kind === 'closed' || e.kind === 'response',\n261\t      )\n262\t      .map((e) => ({ kind: 'event' as const, at: Date.parse(e.at), event: e })),\n263\t  ].sort((a, b) => a.at - b.at)\n264\t\n265\t  useEffect(() => {\n266\t    const el = scrollRef.current\n267\t    if (el) el.scrollTop = el.scrollHeight\n268\t    // Auto-scroll to bottom on Epic switch and on switching back to Discussion.\n269\t  }, [epicId, view, timeline.length])\n270\t\n271\t  // Narrow chats snapshot: the derive helpers only index this Epic's own\n272\t  // entry, and subscribing to the whole `chats` record would re-render this\n273\t  // component on every streaming token of ANY chat (PRD 833 I6).\n274\t  const snapshots: EpicSnapshots = { sessions, chats: chat ? { [epicId]: chat } : {}, jobs: scheduleJobs, prds }\n275\t  const status = epicDisplayStatus(epicId, snapshots)\n276\t  const attachedPrds = epicPrds(epicId, snapshots)\n277\t  const stats = epicStats(epicId, snapshots)\n278\t\n279\t  const projectName = cwd.replace(/\\/+$/, '').split('/').filter(Boolean).pop() ?? cwd\n280\t  const branch = useBranch(cwd)\n281\t  // Job row is the source of truth for Runs (not the PRD join) so a job\n282\t  // whose PRD file was later archived still lists.\n283\t  const epicRuns = scheduleJobs.filter((j) => j.sourcePromptId === epicId)\n284\t\n285\t  const { title, goal } = splitTitleAndGoal(promptSession.goalText)\n286\t\n287\t  const views: { key: ViewKey; label: string }[] = [\n288\t    { key: 'discussion', label: `Discussion ${timeline.length}` },\n289\t    { key: 'prds', label: `PRDs ${attachedPrds.length}` },\n290\t    { key: 'runs', label: `Runs ${epicRuns.length}` },\n291\t  ]\n292\t\n293\t  const onMarkCompleted = () => {\n294\t    setMarkingCompleted(true)\n295\t    void markCompleted(epicId).finally(() => setMarkingCompleted(false))\n296\t  }\n297\t\n298\t  // Mutual exclusion: a chatRunner run in flight (or queued behind one) for\n299\t  // this Epic must finish before Terminal mode can attach the same\n300\t  // claudeSessionId — otherwise a headless resume and an interactive resume\n301\t  // would race on the same transcript.\n302\t  const chatBusy = running || (chat?.queuedPosition ?? 0) > 0\n303\t  const terminalDisabledReason = chatBusy\n304\t    ? 'Chat is running or queued for this Epic — wait for it to finish before switching to Terminal.'\n305\t    : null\n306\t\n307\t  // Returning to Chat (manual toggle or the pane reporting a PTY exit) records\n308\t  // a 'response'-kind marker on the Epic's event chain so the Discussion\n309\t  // thread's audit trail stays honest even though the interactive turns\n310\t  // themselves are never backfilled (out of scope).\n311\t  const returnToChat = () => {\n312\t    // Read the tail fresh rather than off the render-snapshotted\n313\t    // `sessionEvents` — appendPromptSessionEvent's tail-chain check needs the\n314\t    // CURRENT tail, not whatever was current when EpicDetail last rendered.\n315\t    const liveEvents = usePromptSessions.getState().events[epicId] ?? []\n316\t    const tail = liveEvents[liveEvents.length - 1] ?? null\n317\t    if (tail) {\n318\t      appendPromptSessionEvent(epicId, {\n319\t        kind: 'response',\n320\t        causedByEventId: tail.id,\n321\t        text: 'Iterated in Terminal view',\n322\t      })\n323\t    }\n324\t    setMode(epicId, 'chat')\n325\t  }\n326\t\n327\t  const onModeChange = (next: EpicTerminalMode) => {\n328\t    if (next === mode) return\n329\t    if (next === 'terminal') {\n330\t      // Re-read the LIVE chat state, not the render snapshot: a run can start\n331\t      // between the last render and this click (external send, dequeued\n332\t      // ticket, Web Remote prompt) — spawning a PTY then would double-attach\n333\t      // the claudeSessionId (PRD 833 I1).\n334\t      const live = useChat.getState().chats[epicId]\n335\t      const liveBusy = Boolean(live?.running) || (live?.queuedPosition ?? 0) > 0\n336\t      if (terminalDisabledReason || liveBusy) {\n337\t        toast.info('Chat is running or queued for this Epic — wait for it to finish before switching to Terminal.')\n338\t        return\n339\t      }\n340\t      setMode(epicId, 'terminal')\n341\t      return\n342\t    }\n343\t    returnToChat()\n344\t  }\n345\t\n346\t  return (\n347\t    <section className=\"flex h-full min-h-0 min-w-0 flex-1 flex-col bg-bg\" data-testid=\"epic-detail\">\n348\t      <header className=\"border-b border-line px-5 pt-4\">\n349\t        <div className=\"flex items-start gap-3.5\">\n350\t          <div className=\"min-w-0\">\n351\t            <div className=\"mb-1.5 flex items-center gap-2\" data-testid=\"epic-detail-tags\">\n352\t              <EpicStatusChip status={status} />\n353\t              <EpicKindTag kind={promptSession.tag} />\n354\t              <ProjectTag cwd={cwd} name={projectName} />\n355\t              {branch && (\n356\t                <span className=\"font-mono text-xs text-fg-faint\" data-testid=\"epic-detail-branch\">\n357\t                  ⎇ {branch}\n358\t                </span>\n359\t              )}\n360\t            </div>\n361\t            <h1 className=\"m-0 font-serif text-2xl font-semibold leading-tight text-fg\">{title}</h1>\n362\t            {goal && <p className=\"m-0 mt-1.5 max-w-[700px] text-[13.5px] leading-relaxed text-fg-dim\">{goal}</p>}\n363\t          </div>\n364\t          <div className=\"ml-auto flex shrink-0 gap-1.5\">\n365\t            {!isCompleted && (\n366\t              <div\n367\t                className=\"inline-flex items-center gap-0.5 rounded-md border border-line bg-bg-hi p-0.5\"\n368\t                data-testid=\"epic-mode-toggle\"\n369\t              >\n370\t                <button\n371\t                  type=\"button\"\n372\t                  onClick={() => onModeChange('chat')}\n373\t                  aria-pressed={mode === 'chat'}\n374\t                  data-testid=\"epic-mode-chat\"\n375\t                  className={`rounded px-2.5 py-1 text-xs font-semibold ${mode === 'chat' ? 'bg-bg text-fg shadow-sm' : 'text-fg-faint hover:text-fg-dim'}`}\n376\t                >\n377\t                  Chat\n378\t                </button>\n379\t                <button\n380\t                  type=\"button\"\n381\t                  onClick={() => onModeChange('terminal')}\n382\t                  aria-pressed={mode === 'terminal'}\n383\t                  disabled={Boolean(terminalDisabledReason)}\n384\t                  title={terminalDisabledReason ?? 'Switch to an interactive terminal for this Epic'}\n385\t                  data-testid=\"epic-mode-terminal\"\n386\t                  className={`rounded px-2.5 py-1 text-xs font-semibold disabled:cursor-not-allowed disabled:opacity-50 ${mode === 'terminal' ? 'bg-bg text-fg shadow-sm' : 'text-fg-faint hover:text-fg-dim'}`}\n387\t                >\n388\t                  Terminal\n389\t                </button>\n390\t              </div>\n391\t            )}\n392\t            {isCompleted ? (\n393\t              <button\n394\t                type=\"button\"\n395\t                onClick={() => resumeArchived(epicId)}\n396\t                data-testid=\"epic-resume\"\n397\t                className=\"rounded-md bg-accent px-3 py-1.5 text-xs font-semibold text-white hover:bg-accent/90\"\n398\t              >\n399\t                Resume\n400\t              </button>\n401\t            ) : (\n402\t              <button\n403\t                type=\"button\"\n404\t                onClick={onMarkCompleted}\n405\t                disabled={markingCompleted || mode === 'terminal'}\n406\t                title={mode === 'terminal' ? 'Switch back to Chat before marking this Epic completed — it would kill the live Terminal session.' : undefined}\n407\t                data-testid=\"epic-mark-completed\"\n408\t                className=\"rounded-md border border-line bg-bg-hi px-3 py-1.5 text-xs font-semibold text-fg-dim hover:bg-hi disabled:opacity-50\"\n409\t              >\n410\t                {markingCompleted ? 'Marking…' : 'Mark completed'}\n411\t              </button>\n412\t            )}\n413\t          </div>\n414\t        </div>\n415\t\n416\t        <div className=\"mt-3 flex flex-wrap items-center gap-4 pb-2.5\" data-testid=\"epic-meta\">\n417\t          <MetaItem label=\"opened\" value={formatWhen(promptSession.createdAt)} />\n418\t          <MetaItem label=\"last activity\" value={formatWhen(lastActivityAt(promptSession, sessionEvents, turns))} />\n419\t          {stats && <MetaItem label=\"turns\" value={String(stats.turns)} />}\n420\t          {stats && <MetaItem label=\"tool calls\" value={String(stats.toolCalls)} />}\n421\t          {stats?.tokens && <MetaItem label=\"tokens\" value={stats.tokens} />}\n422\t          {/* The Epic IS this claude session — surface the id so it's\n423\t              unambiguous which session scheduler PRDs post their completion\n424\t              responses back to (notifyOriginatingTab keys off it). */}\n425\t          <button\n426\t            type=\"button\"\n427\t            onClick={() => {\n428\t              void navigator.clipboard?.writeText(sessionId).then(\n429\t                () => toast.info('Session id copied'),\n430\t                () => toast.error('Copy failed'),\n431\t              )\n432\t            }}\n433\t            title={`claude session ${sessionId} — click to copy. Scheduler PRDs dispatched from this Epic post their completion responses back into this session's thread.`}\n434\t            data-testid=\"epic-session-id\"\n435\t            className=\"inline-flex items-baseline gap-1.5 text-xs hover:text-fg\"\n436\t          >\n437\t            <span className=\"text-fg-faint\">session</span>\n438\t            <span className=\"font-mono font-semibold text-fg-dim\">{sessionId.slice(0, 8)}…</span>\n439\t          </button>\n440\t        </div>\n441\t\n442\t        {mode === 'chat' && (\n443\t          <div className=\"flex gap-0.5\">\n444\t            <ViewTabs options={views} active={view} onChange={setView} />\n445\t          </div>\n446\t        )}\n447\t      </header>\n448\t\n449\t      {mode === 'terminal' ? (\n450\t        <div className=\"min-h-0 flex-1\" data-testid=\"epic-terminal-pane-wrap\">\n451\t          {/* Keyed by sessionId: forces a full unmount/remount when the\n452\t           *  selected Epic changes rather than reusing this instance across\n453\t           *  two different claudeSessionIds (spawnedRef/exited state assume\n454\t           *  a single session's lifetime). */}\n455\t          <EpicTerminalPane key={sessionId} epicId={epicId} cwd={cwd} sessionId={sessionId} onReturnToChat={returnToChat} />\n456\t        </div>\n457\t      ) : (\n458\t      <div ref={scrollRef} className=\"min-h-0 flex-1 overflow-y-auto px-5 py-5\" data-testid=\"epic-detail-body\">\n459\t        {view === 'discussion' && (\n460\t          <div className=\"grid max-w-[900px] gap-4\">\n461\t            {attachedPrds.length > 0 && (\n462\t              <div className=\"flex flex-wrap items-center gap-2 pb-1\" data-testid=\"epic-attached-prds\">\n463\t                <span className=\"font-mono text-[10.5px] font-semibold uppercase tracking-wide text-fg-faint\">attached</span>\n464\t                {attachedPrds.map((p) => (\n465\t                  <button\n466\t                    key={p.slug}\n467\t                    type=\"button\"\n468\t                    onClick={() => setView('prds')}\n469\t                    className=\"inline-flex items-center gap-1.5 rounded-full border border-line bg-bg-hi px-2.5 py-1 font-mono text-[11px] text-fg-dim hover:bg-hi\"\n470\t                  >\n471\t                    {p.title || p.slug}\n472\t                  </button>\n473\t                ))}\n474\t              </div>\n475\t            )}\n476\t\n477\t            {timeline.length === 0 && !running && (\n478\t              <div\n479\t                className=\"rounded-xl border border-dashed border-rule px-6 py-8 text-center text-sm leading-relaxed text-fg-faint\"\n480\t                data-testid=\"epic-seed-goal\"\n481\t              >\n482\t                {promptSession.goalText}\n483\t              </div>\n484\t            )}\n485\t\n486\t            {timeline.map((item) => {\n487\t              if (item.kind === 'turn') {\n488\t                const t = item.turn\n489\t                const i = turns.indexOf(t)\n490\t                return (\n491\t                  <div key={t.id} id={`epic-detail-turn-${t.id}`}>\n492\t                    <Turn\n493\t                      turn={t}\n494\t                      cwd={cwd}\n495\t                      tabId={epicId}\n496\t                      sessionId={sessionId}\n497\t                      runActive={running && t.role === 'assistant' && i === turns.length - 1}\n498\t                      consentActionDisabled={running}\n499\t                      enableRawSessionActions={false}\n500\t                      linkTarget=\"browser\"\n501\t                      inlineFilePreview\n502\t                      toolStripVariant=\"collapsible\"\n503\t                      needsDecisionStyle\n504\t                    />\n505\t                  </div>\n506\t                )\n507\t              }\n508\t              const e = item.event\n509\t              if (e.kind === 'prd_created') {\n510\t                return (\n511\t                  <div key={e.id} data-testid=\"epic-prd-event\" className=\"flex justify-center\">\n512\t                    <button\n513\t                      type=\"button\"\n514\t                      onClick={() => openPrdSlug(e.prdSlug!)}\n515\t                      title={`Open PRD \"${e.prdSlug}\" in Scheduler`}\n516\t                      className=\"rounded-full border border-line px-2.5 py-1 font-mono text-[11px] text-accent hover:bg-hi\"\n517\t                    >\n518\t                      → dispatched to PRD #{e.prdSlug}\n519\t                    </button>\n520\t                  </div>\n521\t                )\n522\t              }\n523\t              if (e.kind === 'response') {\n524\t                return (\n525\t                  <div key={e.id} data-testid=\"epic-response-event\" className=\"text-center text-[11px] text-fg-faint\">\n526\t                    — {e.text} —\n527\t                  </div>\n528\t                )\n529\t              }\n530\t              return (\n531\t                <div key={e.id} data-testid=\"epic-closed-event\" className=\"text-center text-[11px] text-fg-faint\">\n532\t                  — Epic marked completed —\n533\t                </div>\n534\t              )\n535\t            })}\n536\t          </div>\n537\t        )}\n538\t\n539\t        {view === 'prds' && (\n540\t          <div className=\"grid max-w-[900px] gap-4\" data-testid=\"epic-prds-placeholder\">\n541\t            {attachedPrds.length === 0 ? (\n542\t              <EmptyPlaceholder text=\"No PRD yet for this Epic. Ask Claude in the thread — it will attach here.\" />\n543\t            ) : (\n544\t              <>\n545\t                <div className=\"grid gap-2\">\n546\t                  {attachedPrds.map((p) => (\n547\t                    <PrdCard key={p.slug} prd={p} />\n548\t                  ))}\n549\t                </div>\n550\t                <p className=\"m-0 text-[12.5px] leading-relaxed text-fg-faint\">\n551\t                  Accepting a PRD hands it to the Scheduler as a <span className=\"font-mono\">claude -p</span> job.\n552\t                </p>\n553\t              </>\n554\t            )}\n555\t          </div>\n556\t        )}\n557\t\n558\t        {view === 'runs' && (\n559\t          <div className=\"grid max-w-[900px] gap-2\" data-testid=\"epic-runs-placeholder\">\n560\t            {epicRuns.length === 0 ? (\n561\t              <EmptyPlaceholder text=\"No agent runs in this Epic yet.\" />\n562\t            ) : (\n563\t              epicRuns.map((j) => <RunCard key={j.slug} job={j} />)\n564\t            )}\n565\t          </div>\n566\t        )}\n567\t      </div>\n568\t      )}\n569\t    </section>\n570\t  )\n571\t}\n572\t"}]},"uuid":"d525da82-7461-4cf3-8f7b-f32f70ee79d7","timestamp":"2026-08-01T04:00:14.264Z","toolUseResult":{"type":"text","file":{"filePath":"/home/bilko/Projects/session-manager/src/renderer/components/epics/EpicDetail.tsx","content":"import { useEffect, useRef, useState } from 'react'\nimport { useChat } from '../../state/chat'\nimport { usePromptSessions, type PromptSession, type PromptSessionEvent } from '../../state/promptSessions'\nimport { useScheduleState } from '../../state/scheduleState'\nimport { useEpicTerminal, type EpicTerminalMode } from '../../state/epicTerminal'\nimport { EpicTerminalPane } from './EpicTerminalPane'\nimport { epicDisplayStatus, epicPrds, epicStats, type EpicSnapshots, type EpicPrd } from '../../lib/epicDerive'\nimport { EpicStatusChip, EpicKindTag } from './epic-primitives'\nimport { ProjectTag, PrdStatusPill, SchBadge, verdictLabel, type PrdDisplayStatus } from '../tabs/scheduler/sched-primitives'\nimport { Turn } from '../ChatTranscriptTurn'\nimport { openPrdSlug } from '../../lib/epicNav'\nimport { ViewTabs } from '../ui/ViewTabs'\nimport { AlmanacIcon } from '../layout/AlmanacIcon'\nimport { RunLogViewer } from '../tabs/plans/RunLogViewer'\nimport { formatAgo, formatDuration, formatTimingLabel } from '../../lib/formatTime'\nimport { toast } from '../../state/toast'\nimport { useScheduledPrds } from '../../lib/useScheduledPrds'\nimport { useBranch } from '../../lib/useBranch'\nimport type { ScheduleJob } from '../../../preload/api'\n\n/**\n * Right pane of the redesigned Epics workspace — header (status/kind/project\n * tags, title, goal, actions) + meta row + Discussion/PRDs/Runs view tabs.\n * Built from session-manager-operations/design-mocks/epics/DESIGN_SPEC.md\n * (\"Right pane\") + epics-mock.jsx's EpicDetail/Turn/ToolStrip, translated\n * from inline styles to Tailwind Almanac tokens.\n *\n * Supersedes PromptSessionConversation.tsx as the Epic conversation surface\n * (that file is retired by PRD 829, not here — keep it compiling until then).\n * The Discussion timeline reuses PromptSessionConversation's own merge logic\n * (chat turns + prd_created/closed events, sorted by time) and the shared\n * Turn renderer from ChatTranscriptTurn.tsx, extended behind two new props\n * (toolStripVariant, needsDecisionStyle) rather than forked.\n *\n * PRDs/Runs tab real content is PRD 828's sibling — this file renders\n * placeholder empty states for both. The composer (827-epic-composer) and\n * New Epic card (827-new-epic-card) are separate wave siblings; this file\n * never renders a composer.\n */\n\nconst EMPTY_EVENTS: PromptSessionEvent[] = []\nconst EMPTY_JOBS: ScheduleJob[] = []\n\ntype ViewKey = 'discussion' | 'prds' | 'runs'\n\nfunction MetaItem({ label, value }: { label: string; value: string }) {\n  return (\n    <span className=\"inline-flex items-baseline gap-1.5 text-xs\" data-testid=\"epic-meta-item\">\n      <span className=\"text-fg-faint\">{label}</span>\n      <span className=\"font-mono font-semibold text-fg-dim\">{value}</span>\n    </span>\n  )\n}\n\nfunction EmptyPlaceholder({ text }: { text: string }) {\n  return (\n    <div className=\"rounded-xl border border-dashed border-rule px-6 py-8 text-center text-sm leading-relaxed text-fg-faint\">\n      {text}\n    </div>\n  )\n}\n\n// Relative ages per the mock's EMeta (\"opened 2 days ago · last activity\n// 26m ago\") — absolute timestamps read as a log, not an almanac.\nfunction formatWhen(value: string | number): string {\n  const d = new Date(value)\n  return Number.isNaN(d.getTime()) ? '—' : formatAgo(d.getTime(), Date.now())\n}\n\n/** A PRD file with no matching queue.json job row reads 'draft'\n *  (epicPrds.status carries the raw ScheduleJobStatus otherwise) — map the\n *  one status word STATUS_TONE doesn't key on ('pending') to its Almanac\n *  display name ('queued') rather than forking a second tone table. */\nfunction prdPillStatus(status: EpicPrd['status']): PrdDisplayStatus {\n  return status === 'pending' ? 'queued' : (status as PrdDisplayStatus)\n}\n\n/** Lazy, cached PRD line count — no field for this on EpicPrd/PrdListItem,\n *  so this reads the file body via schedule.readPrd on first render of each\n *  slug and remembers the result module-wide (cards remount often as the\n *  Epic list re-groups/re-sorts). Absent in test mocks that don't stub\n *  readPrd — guarded, so those cards just render without a line count. */\nconst prdLineCountCache = new Map<string, number | null>()\n\nfunction usePrdLineCount(slug: string): number | null {\n  const [count, setCount] = useState<number | null>(() => prdLineCountCache.get(slug) ?? null)\n\n  useEffect(() => {\n    const cached = prdLineCountCache.get(slug)\n    if (cached !== undefined) {\n      setCount(cached)\n      return\n    }\n    if (typeof window.api?.schedule?.readPrd !== 'function') return\n    let cancelled = false\n    window.api.schedule\n      .readPrd(slug)\n      .then((res) => {\n        const lines = res.ok && res.text ? res.text.split('\\n').length : null\n        prdLineCountCache.set(slug, lines)\n        if (!cancelled) setCount(lines)\n      })\n      .catch(() => {\n        prdLineCountCache.set(slug, null)\n        if (!cancelled) setCount(null)\n      })\n    return () => {\n      cancelled = true\n    }\n  }, [slug])\n\n  return count\n}\n\nfunction PrdCard({ prd }: { prd: EpicPrd }) {\n  const lineCount = usePrdLineCount(prd.slug)\n  return (\n    <div\n      className=\"grid grid-cols-[18px_minmax(0,1fr)_auto] items-start gap-3 rounded-xl border border-line bg-bg-hi p-3.5\"\n      data-testid=\"epic-prd-card\"\n    >\n      <span className=\"mt-0.5 text-accent\" aria-hidden=\"true\">\n        <AlmanacIcon name=\"file\" size={16} />\n      </span>\n      <span className=\"min-w-0\">\n        <span className=\"flex flex-wrap items-center gap-2\">\n          <span className=\"font-mono text-[12.5px] font-semibold text-fg\">{prd.slug}</span>\n          <PrdStatusPill status={prdPillStatus(prd.status)} />\n          {lineCount !== null && (\n            <span className=\"font-mono text-[11px] text-fg-faint\" data-testid=\"epic-prd-line-count\">\n              {lineCount} lines\n            </span>\n          )}\n        </span>\n        {prd.title && <span className=\"mt-1 block text-[12.5px] leading-relaxed text-fg-faint\">{prd.title}</span>}\n      </span>\n      <button\n        type=\"button\"\n        onClick={() => openPrdSlug(prd.slug)}\n        title={`Open PRD \"${prd.slug}\" in Scheduler`}\n        data-testid=\"epic-prd-open\"\n        className=\"inline-flex items-center text-fg-faint hover:text-fg-dim\"\n      >\n        <AlmanacIcon name=\"arrowright\" size={15} />\n      </button>\n    </div>\n  )\n}\n\nfunction RunCard({ job }: { job: ScheduleJob }) {\n  const [showLog, setShowLog] = useState(false)\n  const startedMs = job.startedAt ? Date.parse(job.startedAt) : null\n  const finishedMs = job.finishedAt ? Date.parse(job.finishedAt) : null\n  const runtime =\n    startedMs !== null && finishedMs !== null\n      ? formatTimingLabel(finishedMs - startedMs)\n      : startedMs !== null && job.status === 'running'\n        ? formatDuration(Date.now() - startedMs)\n        : null\n\n  return (\n    <div className=\"grid gap-2 rounded-xl border border-line bg-bg-hi p-3.5\" data-testid=\"epic-run-card\">\n      <div className=\"flex flex-wrap items-center gap-2.5\">\n        <span className=\"font-mono text-[12.5px] font-semibold text-fg\">{job.slug}</span>\n        <SchBadge status={job.status} />\n        {runtime && <span className=\"font-mono text-[11px] text-fg-faint\">{runtime}</span>}\n        {job.exitCode !== null && <span className=\"font-mono text-[11px] text-fg-faint\">exit {job.exitCode}</span>}\n        {job.verifierVerdict && (\n          <span className=\"font-mono text-[11px] text-fg-faint\">{verdictLabel(job.verifierVerdict)}</span>\n        )}\n        {job.runId && (\n          <button\n            type=\"button\"\n            onClick={() => setShowLog(true)}\n            data-testid=\"epic-run-view-log\"\n            className=\"ml-auto text-[11.5px] font-semibold text-fg-dim hover:text-fg\"\n          >\n            View log →\n          </button>\n        )}\n      </div>\n      <div className=\"flex flex-wrap gap-3 font-mono text-[11px] text-fg-faint\">\n        <span>started {startedMs !== null ? formatAgo(startedMs, Date.now()) : '—'}</span>\n        <span>finished {finishedMs !== null ? formatAgo(finishedMs, Date.now()) : '—'}</span>\n      </div>\n      {showLog && job.runId && (\n        <RunLogViewer runId={job.runId} slug={job.slug} title={job.title || job.slug} onClose={() => setShowLog(false)} />\n      )}\n    </div>\n  )\n}\n\n/** NewEpicCard.tsx writes goalText as `${title}\\n\\n${goal}` (no separate\n *  title field on PromptSession) — split back apart for the header's h1 +\n *  goal paragraph. Older/Epics with no blank-line separator render the\n *  whole text as the title with no goal paragraph. */\nfunction splitTitleAndGoal(goalText: string): { title: string; goal: string } {\n  const idx = goalText.indexOf('\\n\\n')\n  if (idx === -1) return { title: goalText, goal: '' }\n  return { title: goalText.slice(0, idx), goal: goalText.slice(idx + 2) }\n}\n\n/** Latest activity timestamp across the Epic's audit events + chat turns,\n *  falling back to the Epic's own createdAt when neither has fired yet. */\nfunction lastActivityAt(session: PromptSession, events: PromptSessionEvent[], turns: { at: number }[]): number {\n  const times = [\n    ...events.map((e) => Date.parse(e.at)),\n    ...turns.map((t) => t.at),\n  ].filter((n) => !Number.isNaN(n))\n  if (!times.length) return Date.parse(session.createdAt)\n  return Math.max(...times)\n}\n\ninterface Props {\n  promptSession: PromptSession\n}\n\nexport function EpicDetail({ promptSession }: Props) {\n  const epicId = promptSession.id\n  const { cwd, claudeSessionId: sessionId } = promptSession\n  const isCompleted = promptSession.status === 'completed'\n\n  const chat = useChat((s) => s.chats[epicId])\n  const hydrate = useChat((s) => s.hydrate)\n  const sessions = usePromptSessions((s) => s.sessions)\n  const sessionEvents = usePromptSessions((s) => s.events[epicId]) ?? EMPTY_EVENTS\n  const markCompleted = usePromptSessions((s) => s.markCompleted)\n  const resumeArchived = usePromptSessions((s) => s.resumeArchived)\n  const appendPromptSessionEvent = usePromptSessions((s) => s.appendPromptSessionEvent)\n  const scheduleJobs = useScheduleState((s) => s.snapshot?.jobs) ?? EMPTY_JOBS\n\n  const mode = useEpicTerminal((s) => s.modes[epicId] ?? 'chat')\n  const setMode = useEpicTerminal((s) => s.setMode)\n\n  const [view, setView] = useState<ViewKey>('discussion')\n  const prds = useScheduledPrds()\n  const [markingCompleted, setMarkingCompleted] = useState(false)\n  const scrollRef = useRef<HTMLDivElement | null>(null)\n\n  useEffect(() => {\n    void hydrate({ tabId: epicId, cwd, sessionId })\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [epicId])\n\n  // Tab state resets to Discussion on every Epic change.\n  useEffect(() => {\n    setView('discussion')\n  }, [epicId])\n\n  const turns = chat?.turns ?? []\n  const running = chat?.running ?? false\n\n  // Merged timeline: chat turns + this Epic's own 'prd_created'/'closed'/\n  // 'response' (Terminal-stint marker, PRD 831) audit events, ordered by\n  // time — mirrors PromptSessionConversation.tsx's timeline construction.\n  const timeline = [\n    ...turns.map((t) => ({ kind: 'turn' as const, at: t.at, turn: t })),\n    ...sessionEvents\n      .filter((e): e is PromptSessionEvent & { kind: 'prd_created' | 'closed' | 'response' } =>\n        e.kind === 'prd_created' || e.kind === 'closed' || e.kind === 'response',\n      )\n      .map((e) => ({ kind: 'event' as const, at: Date.parse(e.at), event: e })),\n  ].sort((a, b) => a.at - b.at)\n\n  useEffect(() => {\n    const el = scrollRef.current\n    if (el) el.scrollTop = el.scrollHeight\n    // Auto-scroll to bottom on Epic switch and on switching back to Discussion.\n  }, [epicId, view, timeline.length])\n\n  // Narrow chats snapshot: the derive helpers only index this Epic's own\n  // entry, and subscribing to the whole `chats` record would re-render this\n  // component on every streaming token of ANY chat (PRD 833 I6).\n  const snapshots: EpicSnapshots = { sessions, chats: chat ? { [epicId]: chat } : {}, jobs: scheduleJobs, prds }\n  const status = epicDisplayStatus(epicId, snapshots)\n  const attachedPrds = epicPrds(epicId, snapshots)\n  const stats = epicStats(epicId, snapshots)\n\n  const projectName = cwd.replace(/\\/+$/, '').split('/').filter(Boolean).pop() ?? cwd\n  const branch = useBranch(cwd)\n  // Job row is the source of truth for Runs (not the PRD join) so a job\n  // whose PRD file was later archived still lists.\n  const epicRuns = scheduleJobs.filter((j) => j.sourcePromptId === epicId)\n\n  const { title, goal } = splitTitleAndGoal(promptSession.goalText)\n\n  const views: { key: ViewKey; label: string }[] = [\n    { key: 'discussion', label: `Discussion ${timeline.length}` },\n    { key: 'prds', label: `PRDs ${attachedPrds.length}` },\n    { key: 'runs', label: `Runs ${epicRuns.length}` },\n  ]\n\n  const onMarkCompleted = () => {\n    setMarkingCompleted(true)\n    void markCompleted(epicId).finally(() => setMarkingCompleted(false))\n  }\n\n  // Mutual exclusion: a chatRunner run in flight (or queued behind one) for\n  // this Epic must finish before Terminal mode can attach the same\n  // claudeSessionId — otherwise a headless resume and an interactive resume\n  // would race on the same transcript.\n  const chatBusy = running || (chat?.queuedPosition ?? 0) > 0\n  const terminalDisabledReason = chatBusy\n    ? 'Chat is running or queued for this Epic — wait for it to finish before switching to Terminal.'\n    : null\n\n  // Returning to Chat (manual toggle or the pane reporting a PTY exit) records\n  // a 'response'-kind marker on the Epic's event chain so the Discussion\n  // thread's audit trail stays honest even though the interactive turns\n  // themselves are never backfilled (out of scope).\n  const returnToChat = () => {\n    // Read the tail fresh rather than off the render-snapshotted\n    // `sessionEvents` — appendPromptSessionEvent's tail-chain check needs the\n    // CURRENT tail, not whatever was current when EpicDetail last rendered.\n    const liveEvents = usePromptSessions.getState().events[epicId] ?? []\n    const tail = liveEvents[liveEvents.length - 1] ?? null\n    if (tail) {\n      appendPromptSessionEvent(epicId, {\n        kind: 'response',\n        causedByEventId: tail.id,\n        text: 'Iterated in Terminal view',\n      })\n    }\n    setMode(epicId, 'chat')\n  }\n\n  const onModeChange = (next: EpicTerminalMode) => {\n    if (next === mode) return\n    if (next === 'terminal') {\n      // Re-read the LIVE chat state, not the render snapshot: a run can start\n      // between the last render and this click (external send, dequeued\n      // ticket, Web Remote prompt) — spawning a PTY then would double-attach\n      // the claudeSessionId (PRD 833 I1).\n      const live = useChat.getState().chats[epicId]\n      const liveBusy = Boolean(live?.running) || (live?.queuedPosition ?? 0) > 0\n      if (terminalDisabledReason || liveBusy) {\n        toast.info('Chat is running or queued for this Epic — wait for it to finish before switching to Terminal.')\n        return\n      }\n      setMode(epicId, 'terminal')\n      return\n    }\n    returnToChat()\n  }\n\n  return (\n    <section className=\"flex h-full min-h-0 min-w-0 flex-1 flex-col bg-bg\" data-testid=\"epic-detail\">\n      <header className=\"border-b border-line px-5 pt-4\">\n        <div className=\"flex items-start gap-3.5\">\n          <div className=\"min-w-0\">\n            <div className=\"mb-1.5 flex items-center gap-2\" data-testid=\"epic-detail-tags\">\n              <EpicStatusChip status={status} />\n              <EpicKindTag kind={promptSession.tag} />\n              <ProjectTag cwd={cwd} name={projectName} />\n              {branch && (\n                <span className=\"font-mono text-xs text-fg-faint\" data-testid=\"epic-detail-branch\">\n                  ⎇ {branch}\n                </span>\n              )}\n            </div>\n            <h1 className=\"m-0 font-serif text-2xl font-semibold leading-tight text-fg\">{title}</h1>\n            {goal && <p className=\"m-0 mt-1.5 max-w-[700px] text-[13.5px] leading-relaxed text-fg-dim\">{goal}</p>}\n          </div>\n          <div className=\"ml-auto flex shrink-0 gap-1.5\">\n            {!isCompleted && (\n              <div\n                className=\"inline-flex items-center gap-0.5 rounded-md border border-line bg-bg-hi p-0.5\"\n                data-testid=\"epic-mode-toggle\"\n              >\n                <button\n                  type=\"button\"\n                  onClick={() => onModeChange('chat')}\n                  aria-pressed={mode === 'chat'}\n                  data-testid=\"epic-mode-chat\"\n                  className={`rounded px-2.5 py-1 text-xs font-semibold ${mode === 'chat' ? 'bg-bg text-fg shadow-sm' : 'text-fg-faint hover:text-fg-dim'}`}\n                >\n                  Chat\n                </button>\n                <button\n                  type=\"button\"\n                  onClick={() => onModeChange('terminal')}\n                  aria-pressed={mode === 'terminal'}\n                  disabled={Boolean(terminalDisabledReason)}\n                  title={terminalDisabledReason ?? 'Switch to an interactive terminal for this Epic'}\n                  data-testid=\"epic-mode-terminal\"\n                  className={`rounded px-2.5 py-1 text-xs font-semibold disabled:cursor-not-allowed disabled:opacity-50 ${mode === 'terminal' ? 'bg-bg text-fg shadow-sm' : 'text-fg-faint hover:text-fg-dim'}`}\n                >\n                  Terminal\n                </button>\n              </div>\n            )}\n            {isCompleted ? (\n              <button\n                type=\"button\"\n                onClick={() => resumeArchived(epicId)}\n                data-testid=\"epic-resume\"\n                className=\"rounded-md bg-accent px-3 py-1.5 text-xs font-semibold text-white hover:bg-accent/90\"\n              >\n                Resume\n              </button>\n            ) : (\n              <button\n                type=\"button\"\n                onClick={onMarkCompleted}\n                disabled={markingCompleted || mode === 'terminal'}\n                title={mode === 'terminal' ? 'Switch back to Chat before marking this Epic completed — it would kill the live Terminal session.' : undefined}\n                data-testid=\"epic-mark-completed\"\n                className=\"rounded-md border border-line bg-bg-hi px-3 py-1.5 text-xs font-semibold text-fg-dim hover:bg-hi disabled:opacity-50\"\n              >\n                {markingCompleted ? 'Marking…' : 'Mark completed'}\n              </button>\n            )}\n          </div>\n        </div>\n\n        <div className=\"mt-3 flex flex-wrap items-center gap-4 pb-2.5\" data-testid=\"epic-meta\">\n          <MetaItem label=\"opened\" value={formatWhen(promptSession.createdAt)} />\n          <MetaItem label=\"last activity\" value={formatWhen(lastActivityAt(promptSession, sessionEvents, turns))} />\n          {stats && <MetaItem label=\"turns\" value={String(stats.turns)} />}\n          {stats && <MetaItem label=\"tool calls\" value={String(stats.toolCalls)} />}\n          {stats?.tokens && <MetaItem label=\"tokens\" value={stats.tokens} />}\n          {/* The Epic IS this claude session — surface the id so it's\n              unambiguous which session scheduler PRDs post their completion\n              responses back to (notifyOriginatingTab keys off it). */}\n          <button\n            type=\"button\"\n            onClick={() => {\n              void navigator.clipboard?.writeText(sessionId).then(\n                () => toast.info('Session id copied'),\n                () => toast.error('Copy failed'),\n              )\n            }}\n            title={`claude session ${sessionId} — click to copy. Scheduler PRDs dispatched from this Epic post their completion responses back into this session's thread.`}\n            data-testid=\"epic-session-id\"\n            className=\"inline-flex items-baseline gap-1.5 text-xs hover:text-fg\"\n          >\n            <span className=\"text-fg-faint\">session</span>\n            <span className=\"font-mono font-semibold text-fg-dim\">{sessionId.slice(0, 8)}…</span>\n          </button>\n        </div>\n\n        {mode === 'chat' && (\n          <div className=\"flex gap-0.5\">\n            <ViewTabs options={views} active={view} onChange={setView} />\n          </div>\n        )}\n      </header>\n\n      {mode === 'terminal' ? (\n        <div className=\"min-h-0 flex-1\" data-testid=\"epic-terminal-pane-wrap\">\n          {/* Keyed by sessionId: forces a full unmount/remount when the\n           *  selected Epic changes rather than reusing this instance across\n           *  two different claudeSessionIds (spawnedRef/exited state assume\n           *  a single session's lifetime). */}\n          <EpicTerminalPane key={sessionId} epicId={epicId} cwd={cwd} sessionId={sessionId} onReturnToChat={returnToChat} />\n        </div>\n      ) : (\n      <div ref={scrollRef} className=\"min-h-0 flex-1 overflow-y-auto px-5 py-5\" data-testid=\"epic-detail-body\">\n        {view === 'discussion' && (\n          <div className=\"grid max-w-[900px] gap-4\">\n            {attachedPrds.length > 0 && (\n              <div className=\"flex flex-wrap items-center gap-2 pb-1\" data-testid=\"epic-attached-prds\">\n                <span className=\"font-mono text-[10.5px] font-semibold uppercase tracking-wide text-fg-faint\">attached</span>\n                {attachedPrds.map((p) => (\n                  <button\n                    key={p.slug}\n                    type=\"button\"\n                    onClick={() => setView('prds')}\n                    className=\"inline-flex items-center gap-1.5 rounded-full border border-line bg-bg-hi px-2.5 py-1 font-mono text-[11px] text-fg-dim hover:bg-hi\"\n                  >\n                    {p.title || p.slug}\n                  </button>\n                ))}\n              </div>\n            )}\n\n            {timeline.length === 0 && !running && (\n              <div\n                className=\"rounded-xl border border-dashed border-rule px-6 py-8 text-center text-sm leading-relaxed text-fg-faint\"\n                data-testid=\"epic-seed-goal\"\n              >\n                {promptSession.goalText}\n              </div>\n            )}\n\n            {timeline.map((item) => {\n              if (item.kind === 'turn') {\n                const t = item.turn\n                const i = turns.indexOf(t)\n                return (\n                  <div key={t.id} id={`epic-detail-turn-${t.id}`}>\n                    <Turn\n                      turn={t}\n                      cwd={cwd}\n                      tabId={epicId}\n                      sessionId={sessionId}\n                      runActive={running && t.role === 'assistant' && i === turns.length - 1}\n                      consentActionDisabled={running}\n                      enableRawSessionActions={false}\n                      linkTarget=\"browser\"\n                      inlineFilePreview\n                      toolStripVariant=\"collapsible\"\n                      needsDecisionStyle\n                    />\n                  </div>\n                )\n              }\n              const e = item.event\n              if (e.kind === 'prd_created') {\n                return (\n                  <div key={e.id} data-testid=\"epic-prd-event\" className=\"flex justify-center\">\n                    <button\n                      type=\"button\"\n                      onClick={() => openPrdSlug(e.prdSlug!)}\n                      title={`Open PRD \"${e.prdSlug}\" in Scheduler`}\n                      className=\"rounded-full border border-line px-2.5 py-1 font-mono text-[11px] text-accent hover:bg-hi\"\n                    >\n                      → dispatched to PRD #{e.prdSlug}\n                    </button>\n                  </div>\n                )\n              }\n              if (e.kind === 'response') {\n                return (\n                  <div key={e.id} data-testid=\"epic-response-event\" className=\"text-center text-[11px] text-fg-faint\">\n                    — {e.text} —\n                  </div>\n                )\n              }\n              return (\n                <div key={e.id} data-testid=\"epic-closed-event\" className=\"text-center text-[11px] text-fg-faint\">\n                  — Epic marked completed —\n                </div>\n              )\n            })}\n          </div>\n        )}\n\n        {view === 'prds' && (\n          <div className=\"grid max-w-[900px] gap-4\" data-testid=\"epic-prds-placeholder\">\n            {attachedPrds.length === 0 ? (\n              <EmptyPlaceholder text=\"No PRD yet for this Epic. Ask Claude in the thread — it will attach here.\" />\n            ) : (\n              <>\n                <div className=\"grid gap-2\">\n                  {attachedPrds.map((p) => (\n                    <PrdCard key={p.slug} prd={p} />\n                  ))}\n                </div>\n                <p className=\"m-0 text-[12.5px] leading-relaxed text-fg-faint\">\n                  Accepting a PRD hands it to the Scheduler as a <span className=\"font-mono\">claude -p</span> job.\n                </p>\n              </>\n            )}\n          </div>\n        )}\n\n        {view === 'runs' && (\n          <div className=\"grid max-w-[900px] gap-2\" data-testid=\"epic-runs-placeholder\">\n            {epicRuns.length === 0 ? (\n              <EmptyPlaceholder text=\"No agent runs in this Epic yet.\" />\n            ) : (\n              epicRuns.map((j) => <RunCard key={j.slug} job={j} />)\n            )}\n          </div>\n        )}\n      </div>\n      )}\n    </section>\n  )\n}\n","numLines":572,"startLine":1,"totalLines":572}},"sourceToolAssistantUUID":"e7f3d298-53d7-4f16-a93b-d3e3adc8dd99","session_id":"c9607aa2-8a5c-4489-81c5-8eb3c15882ad","userType":"external","entrypoint":"cli","cwd":"/home/bilko/Projects/session-manager/src/renderer","sessionId":"c9607aa2-8a5c-4489-81c5-8eb3c15882ad","version":"2.1.220","gitBranch":"main"}
