t } from '../../lib/terminalFit'\nimport { transcriptExists } from '../../lib/transcriptExists'\nimport { useEpicTerminal } from '../../state/epicTerminal'\nimport { toast } from '../../state/toast'\n\ninterface Props {\n  epicId: string\n  cwd: string\n  /** The Epic's claudeSessionId — pty.cjs's PtyManager is keyed by an\n   *  arbitrary string, so this reuses that same map without a SessionTab. */\n  sessionId: string\n  onReturnToChat: () => void\n}\n\n/**\n * In-pane xterm + PTY for an Epic's Terminal mode (PRD 831). Deliberately NOT\n * a <Terminal tabId cwd> mount: that component is wired to useSessions' tabs\n * array (isDormant/back-to-chat/startupCommand), and TerminalStage only\n * renders EpicsWorkspace when that array is empty — adding an Epic session as\n * a SessionTab would kick the workspace out from under itself. This pane\n * reuses Terminal.tsx's xterm setup (fit/theme/chunked writes) but owns its\n * own independent spawn/dispose lifecycle keyed directly by claudeSessionId.\n */\nexport function EpicTerminalPane({ epicId, cwd, sessionId, onReturnToChat }: Props) {\n  const hostRef = useRef<HTMLDivElement | null>(null)\n  const xtermRef = useRef<XTerm | null>(null)\n  const spawnedRef = useRef(false)\n  const [exited, setExited] = useState<{ code: number | null } | null>(null)\n  const setAttached = useEpicTerminal((s) => s.setAttached)\n\n  // Attached the instant this pane mounts (before the pty round-trip\n  // resolves) so chat.ts's send() guard blocks immediately on mode switch.\n  //\n  // Deliberately NOT cleared on unmount: this pane unmounts whenever the user\n  // browses to a different Epic, but the PTY keeps running and keeps holding\n  // this Epic's claudeSessionId. Clearing here would let chat.ts dispatch a\n  // headless `--resume` against a session a live interactive claude still\n  // owns. Attachment ends only when the PTY actually ends — on its exit event,\n  // or on the explicit Chat toggle, both of which clear it.\n  useEffect(() => {\n    setAttached(epicId, true)\n  }, [epicId, setAttached])\n\n  useEffect(() => {\n    if (!hostRef.current || spawnedRef.current) return\n    spawnedRef.current = true\n\n    const initial = loadTerminalSettings()\n    const term = new XTerm({\n      fontFamily: '\"IBM Plex Mono\", JetBrains Mono, ui-monospace, Menlo, monospace',\n      fontSize: initial.fontSize,\n      lineHeight: 1.2,\n      cursorBlink: true,\n      allowProposedApi: true,\n      theme: TERMINAL_THEMES[initial.theme],\n    })\n\n    const fit = new FitAddon()\n    term.loadAddon(fit)\n    const guardedFit = () => {\n      const el = hostRef.current\n      if (!el || !canFit(el.clientWidth, el.clientHeight)) return\n      try { fit.fit() } catch { /* ignore */ }\n    }\n    const offSettings = onTerminalSettingsChange((s) => {\n      term.options.theme = TERMINAL_THEMES[s.theme]\n      term.options.fontSize = s.fontSize\n      guardedFit()\n    })\n\n    term.open(hostRef.current)\n    guardedFit()\n    term.focus()\n    xtermRef.current = term\n\n    const { cols, rows } = term\n    const offData = window.api.pty.onData(sessionId, (data) => term.write(data))\n    const offExit = window.api.pty.onExit(sessionId, ({ exitCode }) => {\n      term.write(`\\r\\n\\x1b[38;5;240m[session exited code=${exitCode}]\\x1b[0m\\r\\n`)\n      setAttached(epicId, false)\n      setExited({ code: exitCode ?? null })\n    })\n    term.onData((data) => writeInChunks(sessionId, data))\n    term.onResize(({ cols, rows }) => window.api.pty.resize({ tabId: sessionId, cols, rows }))\n\n    window.api.pty\n      .spawn({ tabId: sessionId, cwd, cols, rows })\n      .then(async ({ reattached }) => {\n        // Reattached to a surviving PTY (renderer reload) — claude is already\n        // running in it; typing the launch command again would inject it into\n        // the live REPL as a prompt. Same guard as Terminal.tsx (PRD 833 I3).\n        if (reattached) return\n        // First interaction of an Epic in Terminal mode has no transcript yet:\n        // `--resume` of a nonexistent session errors out. Same durable\n        // resume-vs-create decision chat.ts's send() makes (PRD 833 I2).\n        const resume = await transcriptExists(cwd, sessionId).catch(() => true)\n        const model = getRawSessionModel()\n        const flag = resume ? `--resume ${shellQuote(sessionId)}` : `--session-id ${shellQuote(sessionId)}`\n        const cmd = `claude --dangerously-skip-permissions ${flag} --model ${model}\\r`\n        setTimeout(() => writeInChunks(sessionId, cmd), 1500)\n      })\n      .catch((err) => {\n        const msg = err instanceof Error ? err.message : String(err)\n        term.write(`\\r\\n\\x1b[31mfailed to start terminal: ${msg}\\x1b[0m\\r\\n`)\n        toast.error(`Terminal failed to start: ${msg}`)\n      })\n\n    const onWinResize = () => guardedFit()\n    window.addEventListener('resize', onWinResize)\n    const ro = new ResizeObserver(() => guardedFit())\n    ro.observe(hostRef.current)\n\n    return () => {\n      window.removeEventListener('resize', onWinResize)\n      ro.disconnect()\n      offData()\n      offExit()\n      offSettings()\n      term.dispose()\n      // Idempotent no-op if the process already exited on its own.\n      window.api.pty.kill(sessionId)\n    }\n  }, [sessionId, cwd, epicId, setAttached])\n\n  if (exited) {\n    return (\n      <div\n        className=\"flex h-full w-full flex-col items-center justify-center gap-3 text-sm text-fg-faint\"\n        data-testid=\"epic-terminal-exited\"\n      >\n        <p>Terminal session exited{exited.code !== null ? ` (code ${exited.code})` : ''}.</p>\n        <button\n          type=\"button\"\n          onClick={onReturnToChat}\n          data-testid=\"epic-terminal-back-to-chat\"\n          className=\"rounded-md bg-accent px-3 py-1.5 text-xs font-semibold text-white hover:bg-accent/90\"\n        >\n          Back to Chat\n        </button>\n      </div>\n    )\n  }\n\n  return (\n    <div\n      ref={hostRef}\n      data-testid=\"epic-terminal-host\"\n      onMouseDown={() => xtermRef.current?.focus()}\n      className=\"h-full w-full bg-bg\"\n    />\n  )\n}\n","structuredPatch":[{"oldStart":125,"oldLines":8,"newStart":125,"newLines":13,"lines":["       offExit()","       offSettings()","       term.dispose()","-      // Idempotent no-op if the process already exited on its own.","-      window.api.pty.kill(sessionId)","+      // The PTY is deliberately LEFT RUNNING. An Epic IS its claude session,","+      // and viewing another Epic must not destroy it — killing here is what","+      // made switching away lose the session's live context (only the","+      // transcript survived, so returning got a cold `--resume`). Teardown is","+      // now owned by the explicit exits: the Chat toggle, Mark completed, and","+      // the PTY's own exit. Main-process output keeps buffering meanwhile and","+      // is replayed on remount, so the viewport comes back with its history.","     }","   }, [sessionId, cwd, epicId, setAttached])"," "]}],"userModified":false,"replaceAll":false},"sourceToolAssistantUUID":"4b5357a8-7032-4add-953a-d03b1ffff2bb","session_id":"c9607aa2-8a5c-4489-81c5-8eb3c15882ad","userType":"external","entrypoint":"cli","cwd":"/home/bilko/Projects/session-manager","sessionId":"c9607aa2-8a5c-4489-81c5-8eb3c15882ad","version":"2.1.220","gitBranch":"main"}
